  // Group 1 is mandatory in UP_TO_N, so a match always populates it. The
  // clause may spell the number out ("seven") or print it as a digit ("7"),
  // and NUMBER_WORDS only holds the spelled-out form ΓÇö so try the numeral
  // first, otherwise a digit would miss the map and silently drop to 1.
  const token = capped[1]!.toLowerCase();
  const limit = /^\d+$/.test(token) ? Number.parseInt(token, 10) : NUMBER_WORDS[token];
  if (limit) return limit;
  // Neither a parseable integer nor a known word (e.g. a number past
  // "twelve"). Stay conservative, but say so rather than under-counting
  // quietly the way the old map-only lookup did.
